// Builds part2-exam-site/ (the real, randomized Part 2 exam) from part2-site/ (the practice
// version). Every file is copied as is, except js/config.js, which switches the mode.
// Run with: node tools/build-part2-exam.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const src = path.join(root, 'part2-site');
const out = path.join(root, 'part2-exam-site');
const EXAM_CONFIG = "// Exam version: new numbers for every version code, no hints or refreshers.\n" +
  "// GENERATED by tools/build-part2-exam.js from part2-site/. Edit files there, then rebuild.\n" +
  "window.PART2_CONFIG = { mode: 'exam', randomize: true, hints: false, title: 'ACC 211 Midterm: Part 2' };\n";

function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true });
  for (const name of fs.readdirSync(from)) {
    const a = path.join(from, name), b = path.join(to, name);
    if (fs.statSync(a).isDirectory()) copyDir(a, b);
    else fs.copyFileSync(a, b);
  }
}
fs.rmSync(out, { recursive: true, force: true });
copyDir(src, out);
fs.writeFileSync(path.join(out, 'js/config.js'), EXAM_CONFIG);
module.exports = { EXAM_CONFIG };
if (require.main === module) console.log('Wrote part2-exam-site/');
